-- ══ Projects ══
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-001', '星火餐饮华南区20店扩张', 'm-001', '餐饮连锁', '明远餐饮集团旗下「明远·粤味」品牌，深耕广式茶点和粤菜快餐赛道。本次联营项目针对深圳和广州的5家新开门店，选址均在日均客流量5万+的核心商圈。单店投资约40万，根据现有门店数据，平均3个月实现盈亏平衡，6个月回本。集团提供统一供应链、品牌运营和人员培训支持。', 500, 380, 8.5, 36, 1.4, 180, 50, 38, 10, 1, 'open', 'TH2K9A', 'class-12', '第12期', NULL, 47, '华南餐饮龙头品牌，月均流水稳定300万', '["18家直营门店，运营超5年","月均流水300万+","已获两轮机构投资"]', '我从2018年开始做餐饮连锁，目前华南区已经有18家店。这次融资主要用于新开5家店，每家店预计3个月回本。欢迎同学们一起参与，有任何问题随时联系我。', '2026-03-10', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-002', '工业视觉检测新产线', 'm-002', '智能制造', '建国智能装备的第三条CNC精密加工产线扩建项目。目前两条产线满负荷运转，订单排期已到6个月后。本次融资用于采购5台五轴联动加工中心及配套检测设备，产能提升60%。核心客户包括比亚迪、大疆和华为的二级供应商体系，合同锁定率超过80%。', 150, 150, 15, 36, 1.5, 320, 6, 6, 25, 1, 'active', 'MF7R3B', 'class-10', '第10期', '["t-002"]', 128, '智能制造赛道，政府重点扶持项目', '["国家高新技术企业","3项核心发明专利","年产值增长率40%"]', '智能制造是我做了12年的老本行，这个项目是我们的第三条产线扩建。产品供不应求，产能是唯一瓶颈。', '2026-01-15', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-003', '优学AI双师课堂全国推广', 'm-003', '教育培训', '芳华供应链科技运营的社区生鲜前置仓项目。已在深圳南山区完成12个社区站点布局，覆盖3.2万家庭用户，月复购率78%。本次融资用于新增8个站点并升级冷链仓配体系，目标覆盖5万家庭。采用产地直采模式，毛利率稳定在32%。', 300, 120, 10, 24, 1.6, 95, 30, 12, 10, 1, 'open', 'HG4N8C', 'class-11', '第11期', NULL, 35, '社区生鲜万亿赛道，轻资产高周转模式', '["覆盖12个社区，3万+家庭用户","月复购率78%","冷链仓配自建完成"]', '社区生鲜是未来10年最大的零售机会。我们已经跑通了单点模型，现在需要资金加速复制。', '2026-03-15', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-004', '鼎盛冷链华东仓网优化', 'm-004', '物流供应链', '「小峰学堂」素质教育品牌的华南区域扩张计划。现有23家校区运营成熟，平均满班率88%，续费率85%。本次融资用于新开5家校区，选址在深圳、东莞、佛山的优质社区商业体。单校区投入约60万，根据历史数据8个月可达盈亏平衡。', 1200, 900, 6.5, 60, 1.3, 480, 60, 45, 20, 1, 'open', 'CL9P5D', 'class-08', '第8期', NULL, 89, '教育培训刚需市场，续费率行业领先', '["在读学员2000+","年续费率85%","已签约5个新校区"]', NULL, '2026-03-05', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-005', 'AI英语口语APP开发', 'm-003', '教育培训', '晓琳跨境电商的北美市场备货融资项目。公司在亚马逊北美站运营3个自有品牌，2024年旺季GMV突破5000万。本次融资用于2025年Q3旺季备货（库存周转约45天），预计带来8000万GMV。FBA仓储和物流体系成熟，退货率控制在5%以内。', 25, 25, 8, 24, 1.5, 12, 5, 5, 5, 1, 'active', 'ED6W2E', 'class-14', '第14期', NULL, 62, '跨境电商蓝海机会，东南亚市场爆发期', '["Shopee/Lazada双平台运营","月GMV突破500万","自有供应链优势"]', '东南亚电商正处于2015年中国电商的爆发期，我们团队在当地运营3年，已经建立了完整的供应链和运营体系。', '2026-02-10', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-006', '华南社区团购联营试点', 'm-001', '社区零售', '已完成的标杆项目。与华南地区3个社区团购站点进行收入分成联营合作，运营周期12个月。项目期间站点月均GMV从20万提升至40万，实现117.3%的投资回报率。该项目验证了收入分成模式在社区零售场景的可行性，为后续规模化提供了数据基础。', 50, 50, 15, 12, 1.5, 32, 10, 10, 5, 1, 'completed', 'FIN001', 'class-12', '第12期', NULL, 156, '社区团购试点项目，已成功完成全部回款', '["3个站点，覆盖8000+家庭","项目已完成，回报率117%","12个月完整回款记录"]', '这个项目已经圆满完成，感谢各位同学的信任与支持！12个月117%的回报，是我们共同创造的成绩。', '2024-11-15', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-007', '精酿啤酒产能扩建', 'm-030', '酒水饮料', '「唐酿」精酿啤酒品牌产能扩建项目。现有酒厂年产能5000吨，已满产。本次融资用于新建年产能3000吨的二期车间，引进德国酿造设备。产品已进入3000+餐饮终端和200+精品超市，扩产后可满足快速增长的市场需求。', 300, 35, 10, 24, 1.5, 25, 30, 4, 10, 1, 'open', 'BER7K2', 'class-16', '第16期', '["t-002"]', 89, '精酿啤酒赛道年增长30%，产品供不应求', '["自建酒厂，德国进口设备","已进入3000+餐饮终端","复购率62%，远超行业平均"]', '精酿啤酒在中国还处于爆发前夜，我们已经验证了产品和渠道，现在需要的就是产能。扩产后预计18个月收回投资。', '2025-08-10', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-008', '宠物医院连锁扩张', 'm-014', '宠物服务', '「爱宠优选」宠物医院品牌的长三角扩张计划。现有12家医院运营成熟，平均单店月营收45万。本次融资用于新开4家医院，选址在杭州、南京、苏州的宠物密度最高社区。单店投入约80万，根据历史数据6个月达盈亏平衡。', 320, 75, 12, 18, 1.4, 55, 32, 8, 10, 1, 'active', 'PET8M3', 'class-16', '第16期', NULL, 156, '宠物医疗刚需赛道，单店模型已验证', '["12家门店成熟运营","年接诊量18万例","单店6个月盈亏平衡"]', '中国宠物数量已超1亿只，宠物医疗是最刚需的赛道。我们的连锁化管理体系是核心壁垒。', '2025-05-20', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-009', '智慧停车平台城市扩张', 'm-035', '智慧城市', '智慧停车运营平台扩张项目。已在50+城市管理15万个车位，年交易额3.2亿。本次融资用于新签约20个城市的停车场资源，部署智能硬件和支付系统。平台抽佣模式，边际成本递减，规模效应显著。', 500, 30, 8, 36, 1.6, 40, 25, 2, 20, 1, 'open', 'PKG9N4', 'class-20', '第20期', '["t-004"]', 203, '智慧城市基础设施，政策红利叠加', '["50+城市，15万车位在管","年交易额3.2亿","平台抽佣，边际成本递减"]', '停车是城市刚需，每个车位都是一个持续产生收入的资产。我们的技术和运营壁垒在于规模效应。', '2025-09-01', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-010', '有机蔬菜基地二期', 'm-008', '现代农业', '华中最大有机蔬菜基地的二期扩建项目。一期基地年供应8000吨有机蔬菜，与盒马、山姆、Ole等高端渠道建立稳定合作。二期计划新增500亩种植面积和2条净菜加工线，预计年增产4000吨，重点拓展净菜和预制菜方向。', 400, 60, 10, 24, 1.5, 35, 27, 4, 15, 1, 'active', 'VEG0A5', 'class-14', '第14期', '["t-001"]', 134, '盒马山姆核心供应商，有机认证壁垒', '["华中最大有机蔬菜基地","盒马、山姆稳定订单","净菜加工毛利率提升至45%"]', '有机农业前期投入大但壁垒极高，认证周期3年让竞争对手很难追赶。我们的渠道关系和品质口碑是最大的护城河。', '2025-04-15', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-011', '光伏组件东南亚产能', 'm-015', '新能源', '浩然新能源在越南的光伏组件代工厂建设项目。国内产能2GW已满产，客户包括中东和东南亚的电站开发商。越南工厂可以规避贸易壁垒，直接服务欧美市场。一期规划500MW产能，土地和厂房已签约。', 800, 0, 8, 36, 1.6, 60, 27, 0, 30, 1, 'open', 'SOL1B6', 'class-18', '第18期', '["t-003"]', 178, '光伏出海，越南产能布局抢占先机', '["国内产能2GW满产","越南工厂规避贸易壁垒","已获欧美客户意向订单"]', '光伏产业链出海是未来5年最确定的趋势。越南工厂建成后，我们可以直接拿到欧美市场30%的价格溢价。', '2025-10-05', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-012', '设计师家居品牌线下体验店', 'm-016', '家居建材', '「木与光」原创设计师家居品牌的线下体验店计划。线上年销2亿+，但家居品类线下体验是成交关键环节。计划在深圳、杭州、成都开设3家400平米体验店，结合场景化展示和即时零售，目标线下带动线上转化率提升30%。', 250, 0, 12, 18, 1.4, 20, 25, 0, 10, 1, 'draft', 'HOM2C7', 'class-18', '第18期', NULL, 0, '天猫家具TOP10品牌，线下体验驱动增长', '["线上年销2亿+，天猫TOP10","自有工厂3间，成本可控","线下体验店模型已在深圳验证"]', NULL, '2025-11-20', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-013', '连锁汽修品牌华东扩张', 'm-017', '汽车后市场', '「快修侠」连锁汽修品牌华东区域扩张。现有42家门店年服务车辆50万台次。本次融资用于新开15家社区店，采用「中心店+卫星店」模式降低单店投入。平均单店日均服务30台车，客单价380元，2个月可盈亏平衡。', 350, 50, 11, 18, 1.4, 30, 35, 5, 10, 1, 'active', 'CAR3D8', 'class-18', '第18期', '["t-003"]', 142, '汽车后市场万亿赛道，连锁化率仅5%', '["42家门店，标准化运营体系","单店2个月盈亏平衡","客户留存率75%"]', '中国汽车保有量3.2亿辆，但连锁化率只有5%。这是一个用标准化打败夫妻店的机会。', '2025-06-10', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-014', '线下剧本杀连锁', 'm-012', '文化传媒', '剧本杀连锁品牌扩张项目。原计划在5个城市开设10家门店，但2025年下半年行业整体下滑，单店营收较峰值下降40%。经与投资参与人协商，决定终止项目并启动清算。已完成部分回款，剩余资金按比例退还。', 200, 25, 15, 12, 1.5, 0, 40, 5, 5, 1, 'terminated', 'DRM4E9', 'class-14', '第14期', NULL, 92, '（项目已终止）', NULL, '很遗憾这个项目没能按预期完成。行业变化超出预判，感谢各位同学的理解和支持，我们已经尽最大努力减少损失。', '2025-02-01', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-015', '健康零食品牌渠道铺货', 'm-020', '食品加工', '「轻悦」健康零食品牌的全渠道铺货融资项目。项目已圆满完成，18个月内将铺货终端从5万个拓展到8万个，品牌年营收从1.2亿增长至1.6亿。投资参与人获得135%的投资回报。', 200, 45, 10, 18, 1.5, 12, 40, 9, 5, 1, 'completed', 'SNK5F0', 'class-20', '第20期', '["t-004"]', 210, '全渠道零食品牌，项目已完成135%回报', '["铺货终端从5万拓至8万","年营收增长33%","18个月完成全部回款"]', '感谢各位同学的信任！这个项目的成功让我更加坚信收入分成模式的价值。「轻悦」会继续成长，期待下一次合作。', '2024-06-01', '2025-12-01');
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-016', '工业物联网平台扩容', 'm-023', '物联网', '工业物联网SaaS平台的客户拓展融资。平台已接入10万+台工业设备，为制造企业提供设备监控和预测维护。本次融资用于扩大销售团队和云服务器集群，目标年内新增200家企业客户，ARR从3000万增长至5000万。', 250, 15, 10, 24, 1.5, 20, 25, 2, 10, 1, 'open', 'IOT6G1', 'class-22', '第22期', '["t-005"]', 97, '工业互联网SaaS，高续费率高毛利', '["10万+设备接入","年续费率92%","毛利率75%"]', '工业互联网是一个慢生意但好生意。我们每接入一台设备，就相当于种下一棵持续产出的果树。', '2025-10-15', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-017', '高端月子中心新店', 'm-036', '母婴服务', '「馨月湾」高端月子护理中心的广州新店项目。现有6家店平均入住率92%，客单价8-15万。广州新店选址在珠江新城核心区，面积1200平米，28间套房，定位城市旗舰店。预计开业3个月达到80%入住率。', 280, 35, 13, 18, 1.4, 25, 28, 4, 10, 1, 'active', 'MOM7H2', 'class-20', '第20期', NULL, 165, '高端月子护理，92%入住率验证模型', '["6家店平均入住率92%","客单价8-15万","珠江新城旗舰店选址"]', '中国每年1000万新生儿，月子中心渗透率不到8%。我们的服务品质和口碑是最好的获客方式，80%的新客来自老客推荐。', '2025-07-01', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-018', '女装品牌数字化转型', 'm-024', '服装零售', '「MAYLINE」女装品牌的线上数字化转型项目。现有180家专柜/门店，但线上占比仅15%。本次融资用于搭建私域运营体系、直播团队和小程序商城，目标12个月内线上占比提升至40%，带动整体营收增长25%。', 200, 20, 12, 18, 1.5, 18, 25, 3, 8, 1, 'open', 'FAS8I3', 'class-22', '第22期', '["t-005"]', 118, '180家门店女装品牌，线上增量空间巨大', '["全国180家专柜/门店","年营收3.2亿","线上占比仅15%，增长空间大"]', '传统服装品牌的数字化不是选择题，是必答题。我们有品牌和供应链基础，缺的只是线上运营能力的投入。', '2025-09-20', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-019', '青少年体育培训全国加盟', 'm-038', '体育产业', '「天宇体育」青少年体育培训品牌的加盟扩张项目。足球、篮球、游泳三大品类，现有40家校区。本次融资用于搭建加盟管理体系和教练培训基地，目标年内新增30家加盟校区，进入10个新城市。', 300, 60, 10, 24, 1.5, 66, 30, 6, 10, 1, 'active', 'SPT9J4', 'class-22', '第22期', '["t-005"]', 134, '双减政策后体育培训爆发，加盟模式轻资产', '["40家校区，3万学员","足球/篮球/游泳三大品类","加盟模式，轻资产快速扩张"]', '双减之后，体育培训的需求翻了3倍。我们用标准化教案和教练培训体系，确保每家加盟校都能保持品质。', '2025-06-20', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-020', '白茶品牌渠道拓展', 'm-041', '茶叶', '「燕归来」福建白茶品牌的渠道拓展融资。自有茶园500亩，线上年销8000万。本次融资用于开拓企业礼品定制渠道和高端茶室体验店，目标进入500家企业的福利采购清单。', 150, 10, 12, 18, 1.4, 15, 30, 2, 5, 1, 'open', 'TEA0K5', 'class-22', '第22期', NULL, 76, '自有茶园，45%复购率，企业礼品蓝海市场', '["自有茶园500亩","线上年销8000万，复购率45%","企业礼品定制客单价高"]', '好茶不怕巷子深，但好渠道能让好茶卖出好价钱。企业礼品市场的客单价是C端的10倍。', '2025-10-01', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-021', '数字营销AI工具平台', 'm-039', '数字营销', '基于服务品牌客户积累的营销经验，开发AI自动化营销工具。已完成MVP产品开发，内部测试效果显著：广告素材生成效率提升5倍，投放ROI平均提升40%。计划面向中小品牌商SaaS化运营。', 180, 0, 10, 24, 1.6, 12, 23, 0, 8, 1, 'draft', 'AIM1L6', 'class-22', '第22期', NULL, 0, 'AI+营销，用技术杠杆放大服务能力', '["已服务安踏、波司登等一线品牌","AI素材生成效率提升5倍","SaaS模式，边际成本趋近于零"]', NULL, '2025-11-25', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-022', '冷链物流华南网络', 'm-037', '冷链物流', '鹏飞冷链物流的华南区域网络扩张。现有冷藏车80台、冷库2万平米。本次融资用于新增30台冷藏车和1个5000平米的分拣中心，打通广深佛莞的冷链配送网络，将配送时效从24小时缩短至6小时。', 350, 45, 9, 24, 1.5, 35, 23, 3, 15, 1, 'open', 'CLD2M7', 'class-20', '第20期', '["t-004"]', 88, '生鲜冷链基础设施，需求刚性增长', '["80台冷藏车，2万平米冷库","目标6小时配送时效","服务3000+商户"]', '冷链物流是生鲜零售的基础设施，谁掌握了最后一公里的冷链能力，谁就掌握了这个市场。', '2025-09-15', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-023', '中式烘焙品牌出海', 'm-026', '烘焙食品', '「凤凰麦坊」国潮中式烘焙品牌的东南亚市场拓展。国内52家门店运营成熟，品牌IP深受年轻消费者喜爱。本次融资用于在新加坡和吉隆坡开设首批3家海外门店，测试东南亚华人市场的接受度。', 200, 35, 12, 18, 1.5, 45, 25, 5, 8, 1, 'active', 'BAK3N8', 'class-12', '第12期', '["t-001"]', 145, '国潮出海，东南亚华人市场巨大', '["国内52家门店成熟运营","国潮IP，年轻人复购率55%","新加坡首店已签约选址"]', '中式烘焙出海是一个全新的蓝海市场。东南亚6亿人口中有4000万华人，国潮文化在年轻一代中非常受欢迎。', '2025-05-15', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-024', '共享办公空间运营', 'm-031', '物业管理', '商务共享办公空间扩张项目。原计划利用物业管理资源开设5个共享办公点，但受远程办公趋势影响，入驻率持续低于预期。运营6个月后与参与人协商终止，已退还未使用资金。', 250, 35, 12, 18, 1.4, 0, 25, 4, 10, 1, 'terminated', 'OFC4O9', 'class-16', '第16期', NULL, 67, '（项目已终止）', NULL, '市场变化超出预期，远程办公对共享办公的冲击比我想象的更大。感谢各位的理解。', '2025-03-01', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-025', '母婴连锁会员体系升级', 'm-010', '母婴零售', '晓婷母婴连锁的会员数字化升级项目，已圆满完成。项目周期15个月，投入资金用于搭建会员小程序、积分体系和精准营销系统。实施后会员月均消费提升28%，整体营收增长22%。投资回报率128%。', 120, 37, 12, 15, 1.4, 45, 24, 8, 5, 1, 'completed', 'BBY5P0', 'class-12', '第12期', '["t-001"]', 189, '会员数字化标杆案例，128%回报率', '["68家门店，15万会员","会员月均消费提升28%","15个月完成全部回款"]', '这个项目让我深刻体会到数字化对实体零售的价值。感谢各位同学的支持，68家门店的15万会员都在享受更好的服务。', '2024-04-01', '2025-07-01');
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-026', '工业废水处理新技术推广', 'm-021', '环保科技', '自主研发的膜生物反应器（MBR）技术在化工行业的推广应用。该技术处理效率比传统方案高40%，成本降低25%。已在3家化工厂验证效果，本次融资用于建设标准化设备生产线和市场推广。', 300, 20, 9, 24, 1.5, 25, 25, 2, 12, 1, 'open', 'H2O6Q1', 'class-20', '第20期', NULL, 92, '环保刚需，自研技术壁垒高', '["服务中石化、宝钢等央企","自研MBR技术，处理效率高40%","3家化工厂验证通过"]', '环保法规只会越来越严，工业废水处理是永远的刚需。我们的技术优势在于效率高、成本低、出水标准稳定。', '2025-10-20', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-027', '医疗器械药房渠道拓展', 'm-019', '医疗健康', '家用智能健康监测设备的药房渠道拓展。已进入2000+药房，主打血压仪、血糖仪和睡眠监测设备。本次融资用于拓展至5000家药房，并推出新品家用尿液分析仪。药房渠道毛利率55%，复购率高。', 180, 35, 12, 18, 1.4, 46, 23, 5, 8, 1, 'active', 'MED7R2', 'class-20', '第20期', '["t-004"]', 108, '家用医疗器械，老龄化社会长期刚需', '["已进入2000+药房渠道","毛利率55%","新品家用尿液分析仪即将上市"]', '中国60岁以上人口2.8亿，家用健康监测设备的渗透率不到10%。这是一个确定性极高的长期赛道。', '2025-07-15', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-028', '高端定制旅行产品升级', 'm-022', '文旅', '甜蜜旅行社的产品升级计划。拟开发3条企业家专属旅行线路（以色列创新考察、日本精益制造研学、北欧设计灵感之旅），融合商务考察与高端休闲，客单价15-25万/人。', 100, 0, 15, 12, 1.4, 15, 20, 0, 5, 1, 'draft', 'TRV8S3', 'class-20', '第20期', NULL, 0, '企业家高端商旅，年服务5000+客户基础', '["年服务企业家5000+","客单价15-25万","融合商务考察与高端休闲"]', NULL, '2025-12-01', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-029', '互联网家装平台升级', 'm-042', '家装服务', '「好装家」互联网家装平台的技术升级和城市扩张。现有平台连接2000+装修师傅，年GMV 1.8亿。本次融资用于开发AI智能报价系统、3D效果预览功能，并拓展至5个新城市。', 220, 15, 10, 24, 1.5, 18, 28, 2, 8, 1, 'open', 'DEC9T4', 'class-22', '第22期', '["t-005"]', 83, '家装平台，AI赋能传统行业', '["2000+装修师傅，年GMV 1.8亿","AI智能报价+3D效果预览","平台抽佣模式，毛利率高"]', '家装行业的信息不对称是最大的痛点。我们用平台化和AI工具，让业主和装修师傅都能获益。', '2025-11-01', NULL);
INSERT OR IGNORE INTO projects (id, name, owner_id, industry, description, target_amount, raised_amount, revenue_share_rate, duration, recovery_multiple, estimated_monthly_revenue, total_shares, raised_shares, share_price, min_shares, status, share_code, initiator_class_id, initiator_class_name, recommended_by_teachers, view_count, highlight_text, highlights, initiator_note, created_at, completed_at) VALUES ('p-030', '短视频MCN机构内容升级', 'm-012', '文化传媒', '雅文传媒MCN机构的内容升级项目，已圆满完成。12个月内孵化了5个百万粉丝账号，签约达人从200人增至350人，整体营收增长55%。投资参与人获得142%的回报率。', 150, 45, 13, 12, 1.5, 78, 30, 9, 5, 1, 'completed', 'MCN0U5', 'class-14', '第14期', '["t-001"]', 198, 'MCN内容升级标杆，142%回报率', '["新增5个百万粉丝账号","签约达人增至350人","12个月营收增长55%"]', '内容行业的核心是人才和创意。这笔融资让我们有能力签约更优质的达人，形成了正向飞轮。感谢各位同学！', '2024-08-01', '2025-08-01');

