INSERT OR IGNORE INTO referrals (id, project_id, project_name, requester_id, requester_name, requester_class, teacher_id, teacher_name, message, status, completed_note, completed_at, created_at) VALUES ('ref-001', 'p-007', '精酿啤酒产能扩建', 'm-011', '吴铭哲', '第14期', 't-002', '陈敏芝', '陈老师好，我对唐颖同学的精酿啤酒项目很感兴趣，我们铭哲新材料也在给食品设备做配件，想了解一下合作可能性，麻烦帮忙引荐。', 'completed', '已拉微信群，双方约了下周三下午茶', '2025-08-14', '2025-08-12');
INSERT OR IGNORE INTO referrals (id, project_id, project_name, requester_id, requester_name, requester_class, teacher_id, teacher_name, message, status, completed_note, completed_at, created_at) VALUES ('ref-002', 'p-009', '智慧停车平台城市扩张', 'm-015', '陈浩然', '第18期', 't-004', '王丽华', '王老师，邱晓明同学的智慧停车项目跟我们新能源充电桩业务有协同空间，希望能认识一下，聊聊合作。', 'completed', '已安排线下咖啡会面，双方达成初步合作意向', '2025-09-07', '2025-09-05');
INSERT OR IGNORE INTO referrals (id, project_id, project_name, requester_id, requester_name, requester_class, teacher_id, teacher_name, message, status, completed_note, completed_at, created_at) VALUES ('ref-003', 'p-011', '光伏组件东南亚产能', 'm-018', '何晓琳', '第18期', 't-003', '张文博', '张老师好，陈浩然同学的光伏越南工厂项目我很有兴趣，我们在东南亚有成熟的物流和渠道资源，想先见面聊聊。', 'completed', '已拉三方群，何晓琳当天就决定参与投资', '2025-10-10', '2025-10-08');
INSERT OR IGNORE INTO referrals (id, project_id, project_name, requester_id, requester_name, requester_class, teacher_id, teacher_name, message, status, completed_note, completed_at, created_at) VALUES ('ref-004', 'p-016', '工业物联网平台扩容', 'm-003', '王建国', '第14期', 't-005', '李国栋', '李老师，冯子轩同学的物联网平台跟我们智能制造业务高度相关，我们工厂正好需要设备监控方案，希望能对接一下。', 'pending', NULL, NULL, '2025-11-15');
INSERT OR IGNORE INTO referrals (id, project_id, project_name, requester_id, requester_name, requester_class, teacher_id, teacher_name, message, status, completed_note, completed_at, created_at) VALUES ('ref-005', 'p-018', '女装品牌数字化转型', 'm-007', '孙丽娜', '第16期', 't-005', '李国栋', '李老师好，曹美玲同学的女装数字化项目和我们美妆品牌的私域运营逻辑很像，想交流一下经验，也考虑参与投资。', 'pending', NULL, NULL, '2025-11-18');
